b506275b Ensure buffer is big enough when parsing PROXY v2 headers
 fuzz/clusterfuzz-testcase-request_fuzzer-5091179189764096 | Bin 0 -> 13 bytes
 src/lib/lwan-request.c                                    |   4 +++-
 2 files changed, 3 insertions(+), 1 deletion(-)
commit b506275b36827f194bc15d77bd6d2f8f7b3b935f
Author: Leandro Pereira <leandro@hardinfo.org>
Date:   Fri Apr 26 08:10:53 2019 -0700

    Ensure buffer is big enough when parsing PROXY v2 headers

    Credit to OSS-Fuzz: https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=14455

diff --git a/src/lib/lwan-request.c b/src/lib/lwan-request.c
index 2406d654..016421ca 100644
--- a/src/lib/lwan-request.c
+++ b/src/lib/lwan-request.c
@@ -223,6 +223,7 @@ parse_proxy_protocol_v1(struct lwan_request *request, char *buffer)
 static char *parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
 {
     struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)buffer;
+    struct lwan_request_parser_helper *helper = request->helper;
     const unsigned int proto_signature_length = 16;
     unsigned int size;
     struct lwan_proxy *const proxy = request->proxy;
@@ -232,6 +233,8 @@ static char *parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
     size = proto_signature_length + (unsigned int)ntohs(hdr->len);
     if (UNLIKELY(size > (unsigned int)sizeof(*hdr)))
         return NULL;
+    if (UNLIKELY(size >= helper->buffer->len))
+        return NULL;

     if (LIKELY(hdr->cmd_ver == PROXY)) {
         if (hdr->fam == TCP4) {
@@ -273,7 +276,6 @@ static char *parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
     buffer += size;

     /* helper->crlfcrlf might be pointing to hdr; adjust */
-    struct lwan_request_parser_helper *helper = request->helper;
     const size_t adjusted_size =
         (size_t)(helper->buffer->value + helper->buffer->len - buffer);
     helper->crlfcrlf = memmem(buffer, adjusted_size, "\r\n\r\n", 4);
abf6eda6 Adjust location of crlfcrlf after parsing PROXY v2 header
 src/lib/lwan-request.c | 23 +++++++++++++----------
 1 file changed, 13 insertions(+), 10 deletions(-)
commit abf6eda654c8336e2ffe4e5c1a5179576da185c5
Author: Leandro Pereira <leandro@hardinfo.org>
Date:   Wed Apr 24 22:02:13 2019 -0700

    Adjust location of crlfcrlf after parsing PROXY v2 header

diff --git a/src/lib/lwan-request.c b/src/lib/lwan-request.c
index 0eba5a65..2406d654 100644
--- a/src/lib/lwan-request.c
+++ b/src/lib/lwan-request.c
@@ -220,20 +220,14 @@ parse_proxy_protocol_v1(struct lwan_request *request, char *buffer)
     return buffer + size;
 }

-static char *
-parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
+static char *parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
 {
-    struct proxy_header_v2 *hdr = (struct proxy_header_v2*)buffer;
+    struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)buffer;
     const unsigned int proto_signature_length = 16;
     unsigned int size;
     struct lwan_proxy *const proxy = request->proxy;

-    enum {
-        LOCAL = 0x20,
-        PROXY = 0x21,
-        TCP4 = 0x11,
-        TCP6 = 0x21
-    };
+    enum { LOCAL = 0x20, PROXY = 0x21, TCP4 = 0x11, TCP6 = 0x21 };

     size = proto_signature_length + (unsigned int)ntohs(hdr->len);
     if (UNLIKELY(size > (unsigned int)sizeof(*hdr)))
@@ -275,7 +269,16 @@ parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
     }

     request->flags |= REQUEST_PROXIED;
-    return buffer + size;
+
+    buffer += size;
+
+    /* helper->crlfcrlf might be pointing to hdr; adjust */
+    struct lwan_request_parser_helper *helper = request->helper;
+    const size_t adjusted_size =
+        (size_t)(helper->buffer->value + helper->buffer->len - buffer);
+    helper->crlfcrlf = memmem(buffer, adjusted_size, "\r\n\r\n", 4);
+
+    return buffer;
 }

 static ALWAYS_INLINE char *identify_http_method(struct lwan_request *request,
